          "name": "Ferocidade",
          "description": "Gatilho O monstro é reduzido a 0 HP.\nEfeito O monstro evita ser nocauteado e permanece com 1 HP, mas seu valor de Ferido aumenta em 1. Quando está Ferido 3, ele não pode mais usar esta habilidade."
