          "description": "Gatilho Um aliado dentro de 30 pés (9 metros) que se beneficiou da ressonância do fogo-fátuo na última hora é alvo de um ataque\nEfeito O fogo-fátuo se detona em uma explosão elementar. Isso concede Pontos de Vida temporários iguais à metade dos Pontos de Vida atuais do fogo-fátuo para aliados dentro de @Template[emanation|distance:30]{30 pés (9 metros)} que se beneficiaram da ressonância do fogo-fátuo na última hora. Esses Pontos de Vida temporários duram 1 hora.\nUm fogo-fátuo que usa esta reação é destruído permanentemente e pode ser restaurado apenas por um ritual de desejo ou efeito similarmente poderoso. Se uma habilidade impedir a destruição do fogo-fátuo (por exemplo, se o fogo-fátuo for invocado e for simplesmente descartado), Accord Essence não terá efeito."
