      "name": "Sombra (Abaddon)",
      "description": "Os caçados aparecem como versões médias de si mesmos de suas vidas anteriores e existem para serem perseguidos e consumidos por demônios.\nQuando um mortal morre, sua alma viaja para Boneyard nos Planos Exteriores, onde é julgado por Pharasma, a deusa dos mortos. Uma vez julgada, sua alma é enviada para a recompensa ou punição final e, no processo, transformada em uma criatura conhecida como sombra. Esta transformação concede à alma um novo corpo, cuja forma é determinada pelas forças filosóficas predominantes do plano para o qual são enviadas. As memórias de uma sombra de sua vida anterior geralmente desaparecem, reduzidas a alguns fragmentos nebulosos, semelhantes a sonhos meio lembrados. Independentemente do tamanho, poder ou natureza da sombra na vida, eles são criaturas Médias na vida após a morte.\nA existência como uma sombra pode durar eras, mas não é necessariamente eterna. Divindades, habitantes poderosos do Grande Além ou até mesmo dos Planos Exteriores podem alterar ainda mais a natureza de uma sombra, reduzindo-a à quintessência bruta, essência espiritual que é então usada para expandir a manifestação física de um plano, ou transformando-a em uma nova forma de vida sobrenatural, como um celestial, monitor ou demônio. Se uma sombra morrer, seu corpo se decompõe em um processo semelhante à decadência, e sua forma reverte para os elementos que compõem seu plano. Isto representa o verdadeiro fim da jornada de uma alma – a sua essência de vida reunindo-se com o coração do Grande Além para ser reciclada na Forja da Criação, alimentando a criação de novas almas.",
