      "name": "Deep One Híbrido",
      "description": "Seja por sua fé devota em Dagon ou por sua própria linhagem biológica, alguns humanos exibem indicadores físicos de sua conexão com os seres profundos.\nHumanóides pesados, anfíbios e imortais, conhecidos como profundos, habitam áreas costeiras e fossas oceânicas profundas por toda Golarion. Embora a maioria deseje simplesmente ser deixada em paz, outros trabalham incansavelmente para crescerem nas suas fileiras.",
