      "actions": {
        "xldFS8pxvUDODZeT": {
          "name": "Vontade Feroz",
          "description": "Gatilho O dragão doméstico consegue um teste de resistência contra um efeito mental mágico\nEfeito O dragão doméstico envia uma explosão de feedback mágico na fonte do efeito, causando 2d6 de dano [mental] (teste (vontade, dc:16, básico)) àquela criatura. Se falhar na resistência, a criatura também sofre 1 Lentidão por 1 rodada."
        },
        "O4iNJ257JLJqRJwN": {
          "name": "Sopro Prateado",
          "description": "O dragão da casa respira uma @Template[type:cone|distance:10] de névoa prateada. Cada criatura dentro da névoa deve ter sucesso em um teste (vontade, dc:16) de resistência ou ficará Estupefato 2 por 1 rodada. O dragão da casa não pode usar Sopro Prateado novamente por 1d4."
        },
        "8vyRXD8spS1ZT642": {
          "name": "Golpe Prateado",
          "description": "Os dracos domésticos afiam suas mandíbulas em ornamentações de prata até incorporarem pedaços de prata em seus dentes. Suas mandíbulas Strike contam como prata."
        }
      },
