        "axj5ih5pp7f0M7V5": {
          "name": "Tecelagem Iivlar",
          "description": "O sábio tem fios planos entrelaçados em sua pele. Este tópico brilha com pouca luz em um @Template[type:emanation|distance:10]. Eles podem sustentar para extinguir, reativar ou ajustar a coloração desta luz."
        },
        "rIjm9mCf0cXSsHwh": {
          "name": "Traço Avião-Hopper",
          "description": "Frequência uma vez por dia\nEfeito O sábio jotunborn se move com rapidez entre limites planares para encurtar sua jornada. O sábio Passos; esse movimento não desencadeia reações. Assim que o Passo for concluído, o sábio ganha um bônus de status de +5 em sua Velocidade até o início do próximo turno."
        }
