          "description": "Requisitos A sanguessuga gigante tem uma criatura viva agarrada ou contida\nEfeito A sanguessuga gigante drena o sangue da criatura que agarrou ou prendeu. Isso causa 2d4[perfurante] de dano (teste de resistência (fortitude, dc:18, básico)). Uma criatura que sofre qualquer dano por ter seu sangue drenado por uma sanguessuga gigante é Drenada 1 até receber qualquer tipo ou quantidade de cura."
